<template>
	<view class="grade">
		<view class="btn-box">
			<view class="del-tex">
				操作
			</view>
			<view class="del-btn" @click="del">
				删除
			</view>
		</view>

		<view class="list">
			<view class="item" v-for="item in list" :key="item.cartId">
				<view class="item-titbox" @click="to(`/pages/index/courseDetail?courseId=${item.courseId}`)">
					<text class="item-type" :class="item.bg">{{item.subjectName}}</text>
					<!-- <text class="item-type shuxue">数学</text> -->
					<!-- <text class="item-type yuwen">语文</text> -->
					<!-- <text class="item-type wuli">物理</text> -->
					<text class="item-title">{{item.courseTitle}}</text>
				</view>
				<view class="item-time ovHide">{{item.desc}}</view>
				<view class="item-address">
					<text class="iconfont icon-fenxiangsheding-dizhi"></text>
					<text class="adres-tex ovHide">{{item.campusAddress}}</text>
				</view>
				<view class="item-flex">
					<view class="item-name">
						<text class="iconfont icon-navicon-grkh"></text>{{item.teacherName}}
					</view>
					<view class="item-select" :class="{not:selectIds.indexOf(item.cartId) == -1}"
						@click="selectChange(item.cartId)">
						<text class="iconfont icon-duigou" v-if="selectIds.indexOf(item.cartId) != -1"></text>
					</view>
				</view>
				<view class="line"></view>
				<view class="item-end">
					<view class="end-left">
						<view class="end-is">共{{item.sessionCount}}次课</view>
						<!-- <view class="end-num">共8次课</view> -->
					</view>
					<view class="end-right">
						<view class="end-money">
							<text class="danwei">¥</text>
							<text class="price">{{item.price}}</text>
						</view>
					</view>
				</view>
			</view>
		</view>

		<!-- 添加选课单 -->
		<view class="add-box" :style="{paddingBottom: paddingbottom + 'rpx'}">
			<view class="price-box">
				<view class="price-num">
					<text class="heji">合计</text>
					<text class="danwei">¥</text>
					<text class="price">{{sumMoney}}</text>
				</view>
			</view>
			<view class="add-btn" @click="checkCart">立即报名</view>
		</view>

		<!-- 		加载提示 -->
		<view class="loading" v-if="showLoading">
			<text style="--i:1">加</text>
			<text style="--i:2">载</text>
			<text style="--i:3">中</text>
			<text style="--i:4">.</text>
			<text style="--i:5">.</text>
			<text style="--i:6">.</text>
		</view>

	</view>
</template>
<script>
	import {
		loaded,
		loading,
		toast,
		redirectTo,
		navigateTo
	} from '@/utils/index.js';
	import {
		img_PATH
	} from '@/config';
	import {
		queryCartList,
		removeFromCart,
		checkCartCourses,
		createOrder
	} from '@/api/index.js'
	export default {
		data() {
			return {
				imgurl: img_PATH,
				CustomBar: this.CustomBar,
				showLoading: false,
				showNone: false,
				list: [],
				selectIds: [],
				sumMoney: 0,
			};
		},
		computed: {
			paddingbottom() {
				const res = wx.getSystemInfoSync()
				const {
					screenHeight,
					safeArea: {
						bottom
					}
				} = res
				if (screenHeight && bottom) {
					let safeBottom = screenHeight - bottom
					return safeBottom
				} else {
					return 0
				}
			}
		},
		components: {

		},
		onShow() {
			this.getList()
		},
		onLoad() {

		},
		created() {

		},
		// 触底的事件
		onReachBottom() {

		},
		methods: {
			// 数据初始化
			async getList() {
				this.sumMoney = 0
				this.list = []
				this.selectIds = []
				this.showLoading = true
				let _data = await queryCartList();
				if (_data.code == 200) {
					this.showLoading = false
					this.list = _data.data
					// this.list.map(item => {
					// 	this.selectIds.push(item.cartId)
					// })
					// this.sum()
				}
			},

			// 删除课程
			async del() {
				if (this.selectIds.length == 0) return toast('请选择要删除的课程')
				let _data = await removeFromCart(this.selectIds.join(','));
				toast(_data.msg)
				if (_data.code == 200) {
					this.getList()
				}
			},

			// 选中和取消
			selectChange(cartId) {
				const index = this.selectIds.indexOf(cartId)
				if (index != -1) {
					this.selectIds.splice(index, 1);
				} else {
					this.selectIds.push(cartId)
				}
				this.sum()
			},

			// 计算价格
			sum() {
				let sumNuM = 0;
				this.selectIds.map(cartId => {
					this.list.map(item => {
						if (cartId == item.cartId) {
							sumNuM += Number(item.price)
						}
					})
				})
				this.sumMoney = sumNuM
			},

			// 校验课程是否存在
			async checkCart() {
				if (this.selectIds.length == 0) return toast('请选择要报名的课程')
				let _data = await checkCartCourses(this.selectIds.join(','));
				if (_data.code == 200) {
					this.createOrder()
				} else {
					toast(_data.msg)
				}
			},

			// 创建订单
			async createOrder() {
				let _data = await createOrder(this.selectIds.join(','));
				if (_data.code == 200) {
					this.to(`/pages/index/orderPay?orderId=${_data.data.orderId}`)
				} else {
					toast(_data.msg)
				}
			},


			to(path) {
				navigateTo(path)
			},
		},

	}
</script>

